<?php require 'db.php'; header('Content-Type: application/json; charset=utf-8'); try{$a=$_POST['accion']??$_GET['accion']??'listar'; if($a==='listar'){$s=$pdo->query('SELECT s.*,b.nombre barco_nombre FROM salidas s LEFT JOIN barcos b ON b.no_matricula=s.barcos_no_matricula ORDER BY s.fecha DESC,s.hora DESC');echo json_encode(['ok'=>true,'datos'=>$s->fetchAll()],JSON_UNESCAPED_UNICODE);exit;} if($a==='crear'){$s=$pdo->prepare('INSERT INTO salidas(hora,fecha,destino,barcos_no_matricula) VALUES(?,?,?,?)');$s->execute([$_POST['hora'],$_POST['fecha'],trim($_POST['destino']),$_POST['barcos_no_matricula']]);echo json_encode(['ok'=>true,'mensaje'=>'Salida creada correctamente.'],JSON_UNESCAPED_UNICODE);exit;} if($a==='actualizar'){$s=$pdo->prepare('UPDATE salidas SET hora=?,fecha=?,destino=?,barcos_no_matricula=? WHERE Id=?');$s->execute([$_POST['hora'],$_POST['fecha'],trim($_POST['destino']),$_POST['barcos_no_matricula'],$_POST['Id']]);echo json_encode(['ok'=>true,'mensaje'=>'Salida actualizada correctamente.'],JSON_UNESCAPED_UNICODE);exit;} if($a==='eliminar'){$s=$pdo->prepare('DELETE FROM salidas WHERE Id=?');$s->execute([$_POST['Id']]);echo json_encode(['ok'=>true,'mensaje'=>'Salida eliminada correctamente.'],JSON_UNESCAPED_UNICODE);exit;} http_response_code(400);echo json_encode(['ok'=>false,'mensaje'=>'Acción no válida.'],JSON_UNESCAPED_UNICODE);}catch(PDOException $e){http_response_code(400);echo json_encode(['ok'=>false,'mensaje'=>$e->getMessage()],JSON_UNESCAPED_UNICODE);}
?>
